(()=>{function decorate(){document.body.classList.toggle('config-d',state.page==='config');if(state.page!=='config')return;document.querySelector('.shell>.side [data-page="config"]')?.classList.add('active');document.querySelectorAll('.cfg-section>table').forEach(table=>{const wrap=document.createElement('div');wrap.className='cfg-table-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','配置数据，可横向滚动');table.before(wrap);wrap.append(table)})}const base=render;render=function(){base();decorate()};decorate()})();